def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2
    if count == 0:
        return None
    average = (v1 + v2) / count
    return {
        "value": average,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": count,
            "average": average,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
